cd $(git rev-parse --show-toplevel) && python3 - <<'EOF'
p='parser/parser.go'
s=open(p).read()
old='''			case "nil":
				node = p.createNode(&NilNode{}, token.Location)
				if node == nil {
					return nil
				}
				return node
			default:
				if p.current.Is(Bracket, "(") {
					node = p.parseCall(token, []Node{}, true)
				} else {
					node = p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
					if node == nil {
						return nil
					}
				}
			}'''
new='''			case "nil":
				node = p.createNode(&NilNode{}, token.Location)
				if node == nil {
					return nil
				}
				return node
			case "try":
				if p.current.Is(Bracket, "{") {
					node = p.parseTryBlock(token)
					if node == nil {
						return nil
					}
					return p.parsePostfixExpression(node)
				}
				if p.current.Is(Bracket, "(") {
					node = p.parseCall(token, []Node{}, true)
					if node == nil {
						return nil
					}
					return p.parsePostfixExpression(node)
				}
				p.error("unexpected token %v after try, expected ( or {", p.current)
				return nil
			case "retry":
				if p.current.Is(Bracket, "(") {
					node = p.parseCall(token, []Node{}, true)
				} else {
					node = p.createNode(&RetryNode{}, token.Location)
					if node == nil {
						return nil
					}
				}
				return p.parsePostfixExpression(node)
			default:
				if p.current.Is(Bracket, "(") {
					node = p.parseCall(token, []Node{}, true)
				} else {
					node = p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
					if node == nil {
						return nil
					}
				}
			}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
print("done")
EOF

